FIXES_122["source/devices/device_machines.c#farrate"] = [
("""boolean machine_update(
	long machine_index)
{""", """#ifdef HALO_PSP
/* psp_fixups.py (FIXES_122): "machinesfar" (objects.c). A far, unseen
always-moving machine's tick without its update: only the step
machine_update's first lines make, the same operations on the same values,
so its position and its group's value stay where every-tick updates put
them. Only while device_update would leave the machine alone (its power
steady, nothing asked of its position group); else 0, nothing changed.
Without step, only whether it could */
int psp_machine_step_alone(long machine_index, int step)
{
	struct machine_datum *machine = machine_get(machine_index);
	struct machine_definition *definition = machine_definition_get(machine->definition_index);
	struct device_group_datum *group = NULL;

	if (definition->machine.type != _machine_type_platform ||
		machine->device.power_velocity != 0.0f || machine->device.position_velocity != 0.0f)
		return 0;
	if (machine->device.power_group_index != NONE &&
		((struct device_group_datum *)datum_get(device_groups_data, machine->device.power_group_index))->actual_value !=
			machine->device.power)
		return 0;
	if (machine->device.position_group_index != NONE)
	{
		group = (struct device_group_datum *)datum_get(device_groups_data, machine->device.position_group_index);
		if (group->actual_value != machine->device.position)
			return 0;
	}
	if (!step)
		return 1;
	/* as device_update does for a device its group leaves alone */
	if (group)
		machine->device.delay_ticks = 0;
	machine->device.position +=
		(1.0f - machine->device.power) * definition->device.runtime_maximum_depowered_position_velocity +
		machine->device.power * definition->device.runtime_maximum_powered_position_velocity;
	if (machine->device.position >= 1.0f)
	{
		machine->device.position -= 1.0f;
	}
	/* the relink this asks for is made at the next update */
	machine->device.flags |= FLAG(_device_position_changed_bit);
	if (group)
		group->actual_value = machine->device.position;
	return 1;
}
#endif

boolean machine_update(
	long machine_index)
{"""),
]


FIXES_123 = {}
# ai_profile_update samples its meters every tick for the AI debug display
# (ai_show_* and profile_display): two walks over every actor (units, swarm
# actors) and 28 meters' histories, each with a float division. Nothing in
# play reads a meter's sample, value or history; the only reader outside the
# display is the port's perception (FIXES_121, FIXES_122), which uses the
# line-of-sight and collision accumulators as counters within one tick and
# relies on them starting each tick at 0. So with the display off, only that
# reset is done. The display's history starts over when it is turned on.
# "aiprofilefull" (keep.txt): every tick's samples as before
FIXES_123["source/ai/ai_profile.c#skip"] = [
("""void ai_profile_update(
	void)
{
	short index;
	struct ai_meter_definition const *definition = global_ai_meter_definitions;
	struct ai_meter *meter = ai_profile.meters;
""", """#ifdef HALO_PSP
/* psp_fixups.py (FIXES_123): whether anything shows the meters */
int psp_keep(const char *name);
extern boolean profile_display;

static boolean psp_ai_profile_shown(
	void)
{
	return profile_display || psp_keep("aiprofilefull") ||
		(ai_profile.show && (ai_profile.show_stats || ai_profile.show_actors || ai_profile.show_swarms ||
			ai_profile.show_paths || ai_profile.show_line_of_sight || ai_profile.show_prop_types));
}
#endif

void ai_profile_update(
	void)
{
	short index;
	struct ai_meter_definition const *definition = global_ai_meter_definitions;
	struct ai_meter *meter = ai_profile.meters;

#ifdef HALO_PSP
	/* psp_fixups.py (FIXES_123): the accumulators start the tick at 0, as
	after a full update; the rest is the display's alone */
	if (!psp_ai_profile_shown())
	{
		for (index = 0; index < NUMBER_OF_AI_METERS; index++)
		{
			meter[index].accumulator = 0;
		}
		return;
	}
#endif
"""),
]


