# A flare's ray asks the level first. The flare test (b31, b116) casts a ray
# from the eye to the flare against the level and the objects in its way,
# and a flare shows only if the ray meets nothing or the sky. The level is
# walked first and objects are tested only in the leaves the ray crossed up
# to its wall, where a hit can only bring the answer nearer: so when the
# level alone meets a wall that is not sky, the answer is "hidden" whatever
# the objects say, and their test is skipped. On c20 the
# flare test was 6.9 ms a frame and nine flare answers in ten hidden. Exact:
# the same answers; only the objects' marks (the ray stamped the objects it
# tested) differ. Keep words "flaresfull" (the full test always, as before)
# and "flarescheck" (both, and the answers compared in the log)
FIXES_129["source/rasterizer/xbox/rasterizer_xbox_widgets.c#walls"] = [
("""/* build 116: characters in a flare's way (b113 #2) */
static unsigned long psp_flare_bipeds = 0;""",
 """/* build 116: characters in a flare's way (b113 #2) */
static unsigned long psp_flare_bipeds = 0;
static int psp_flare_walls = -1, psp_flare_walls_check = 0, psp_flare_level_short = 0, psp_flare_debug = 0;
unsigned long psp_flare_walls_hidden = 0, psp_flare_walls_checked = 0, psp_flare_walls_differed = 0; /* psp_ge.c logs them */"""),
("""				/* the level's sky surfaces (no material) are where the
				sky is drawn: a ray that meets one has reached the sky */
				if (!collision_test_vector(
					FLAG(_collision_test_front_facing_surfaces_bit) |
						FLAG(_collision_test_ignore_invisible_surfaces_bit) |
						FLAG(_collision_test_structure_bit) |
						FLAG(_collision_test_objects_bit) |
						_collision_test_objects_sight_blocking_flags | psp_flare_bipeds,
					&global_window_parameters.camera.position,
					&ray,
					NONE,
					&collision) ||
					(collision.type == _collision_result_structure && collision.material_index == NONE))
					visible = (long)(pixel_count * MIN(on_screen, 1.0f));
				psp_ge_widget_occlusion(visible > 0);""",
 """				{
					boolean level_hides = FALSE;

					if (psp_flare_walls < 0)
					{
						psp_flare_walls = !psp_keep("flaresfull");
						psp_flare_walls_check = psp_keep("flarescheck") != 0;
						psp_flare_level_short = psp_keep("flaresshort") != 0;
						psp_flare_debug = psp_keep("flaresdebug") ? 40 : 0;
					}
					/* the level alone, with the full test's surface flags:
					a wall that is not sky hides the flare whatever the
					objects say, as they can only meet the ray nearer.
					This ray runs to the flare's own point (all but 2 cm),
					as the Xbox's test square is depth-tested there: the
					ray above stops 0.15 short so as not to meet the
					flare's own object, and the level has no such object.
					Stopped short, a wall within 0.15 of a lamp on its far
					side (or of a door's lamp slid into it) let the flare
					shine through ("flaresshort": as before) */
					if (psp_flare_walls || psp_flare_walls_check)
					{
						real_vector3d level_ray = ray;

						if (!psp_flare_level_short)
						{
							real length;

							vector_from_points3d(&global_window_parameters.camera.position, point, &level_ray);
							length = magnitude3d(&level_ray);
							if (length > 0.05f)
								scale_vector3d(&level_ray, (length - 0.02f) / length, &level_ray);
						}
						level_hides = collision_test_vector(
							FLAG(_collision_test_front_facing_surfaces_bit) |
								FLAG(_collision_test_ignore_invisible_surfaces_bit) |
								FLAG(_collision_test_structure_bit),
							&global_window_parameters.camera.position,
							&level_ray,
							NONE,
							&collision) && collision.material_index != NONE;
						if (psp_flare_debug > 0)
						{
							psp_flare_debug--;
							platform_psp_log("flaresdebug: flare %ld at %.2f %.2f %.2f, %.2f from the eye: level %s (t %.3f, material %d)",
								index, point->x, point->y, point->z, magnitude3d(&level_ray),
								level_hides ? "hides it" : "clear", level_hides ? collision.t : 1.0f,
								(int)collision.material_index);
						}
					}
					if (level_hides && !psp_flare_walls_check)
					{
						psp_flare_walls_hidden++;
					}
					else
					{
						/* the level's sky surfaces (no material) are where the
						sky is drawn: a ray that meets one has reached the sky */
						if (!collision_test_vector(
							FLAG(_collision_test_front_facing_surfaces_bit) |
								FLAG(_collision_test_ignore_invisible_surfaces_bit) |
								FLAG(_collision_test_structure_bit) |
								FLAG(_collision_test_objects_bit) |
								_collision_test_objects_sight_blocking_flags | psp_flare_bipeds,
							&global_window_parameters.camera.position,
							&ray,
							NONE,
							&collision) ||
							(collision.type == _collision_result_structure && collision.material_index == NONE))
							visible = (long)(pixel_count * MIN(on_screen, 1.0f));
						if (psp_flare_walls_check)
						{
							psp_flare_walls_checked++;
							if (level_hides)
								psp_flare_walls_hidden++;
							if (level_hides && visible > 0)
								psp_flare_walls_differed++;
						}
					}
				}
				psp_ge_widget_occlusion(visible > 0);"""),
]

# The fractions of the animations and periodic functions in single precision
# (E16 again, lever PQ). (real)fmod((double)x, 1.0) and
# (real)floor(fabs(x)) take the double library on the PSP (software, a few
# hundred cycles a call), for a float x every time: the frame fractions of
# every animated node's channels, the aim and the overlays, and the periodic
# functions that drive objects' and shaders' function values. For a normal
# float the fraction is x less its integer part, a float exactly, so the
# single-precision answer has the same bits; zeros keep fmod's sign, and
# infinities and NaNs take the double path. Build 115 held this back on a
# check made before statecmp's play hash; the whole-state differences it saw
# (the decal vertex cache, objects, actors) are those every build pair shows.
# Keep words "fractiondouble" (the double path, as before) and
# "fractioncheck" (both, compared; the heartbeat logs the count)
FIXES_129["port/include/halo_math.h#fraction"] = [
("""#define fmod(x, y) PSP_NARROW2(fmod, (fmod), x, y)
#endif
""",
 """#define fmod(x, y) PSP_NARROW2(fmod, (fmod), x, y)

/* (real)fmod((double)x, 1.0) and (real)floor(fabs((double)x)) for a float x
with the same bits, in single precision. A normal float's fraction is x less
its integer part, which a float holds exactly (the subtraction loses
nothing); |x| below 1 is its own fraction, and from 2^23 up every float is
an integer. fmod gives a zero the sign of x. Infinities and NaNs take the
double path. psp_platform.c reads the keep words */
extern int psp_fraction_word; /* -1 until read; 0 single, 1 double, 2 both, compared */
int psp_fraction_word_read(void);
float psp_fraction_compared(float x, float single, int floor_of_abs);
static inline float psp_fraction_single(float x)
{
	union { float f; unsigned int u; } bits;
	unsigned int exponent;
	float fraction;

	bits.f = x;
	exponent = (bits.u >> 23) & 0xff;
	if (exponent < 127)
		return x;
	if (exponent >= 127 + 23)
		return x < 0.0f ? -0.0f : 0.0f;
	fraction = x - (float)(int)x;
	if (fraction == 0.0f)
		return x < 0.0f ? -0.0f : 0.0f;
	return fraction;
}
static inline float psp_fraction_of(float x)
{
	int word = psp_fraction_word >= 0 ? psp_fraction_word : psp_fraction_word_read();
	union { float f; unsigned int u; } bits;

	bits.f = x;
	if (word == 1 || ((bits.u >> 23) & 0xff) == 0xff)
		return (float)(fmod)((double)x, 1.0);
	if (word == 2)
		return psp_fraction_compared(x, psp_fraction_single(x), 0);
	return psp_fraction_single(x);
}
static inline float psp_floor_of_abs(float x)
{
	int word = psp_fraction_word >= 0 ? psp_fraction_word : psp_fraction_word_read();

	if (word == 1 || x != x)
		return (float)(floor)((fabs)((double)x));
	if (word == 2)
		return psp_fraction_compared(x, floorf(fabsf(x)), 1);
	return floorf(fabsf(x));
}
#endif
"""),
]
